// This file is generated by AI.

// 通用确认框流程 (问一句再动手)。
//
// 与 `unsaved.ts` 同一个套路: 待执行的动作用模块级变量存住, store 里只放一个开关。
//
// **不要用 `window.confirm`**: 在 Tauri 的 WebView 里它不一定真的弹窗 —— 有的环境直接
// 返回, 于是"询问"变成"悄悄放行"。关闭配音工作台、撤下正在跑的任务这类有后果的操作不能
// 赌这个, 而且原生弹窗与编辑器里其它确认框长得完全不一样。
//
// 用法:
// ```ts
// if (需要确认) {
//   requestConfirm({ title, description, confirmLabel, action: () => 真正的动作() });
//   return;   // 立即返回, 由用户点确认后执行 action
// }
// 真正的动作();
// ```

import { useAppStore } from './state/store';

interface PendingConfirm {
  title: string;
  description: string;
  confirmLabel: string;
  /** 危险操作 (取消任务、丢弃内容) 的确认按钮用危险色 */
  danger?: boolean;
  /**
   * 只是"告诉用户一件事": 不显示取消按钮, 只有一个确认键。
   *
   * 失败提示走这里而不是在页面上插一行红字 —— 页面内容不该因为一次操作而变样
   * (列表少一行、多一行错误都算), 提示应当是**盖在上面**的一层。
   */
  info?: boolean;
  /** 用户点确认后执行的动作 */
  action: () => void;
}

let pending: PendingConfirm | null = null;

/** 请求一次确认; 用户点确认后才执行 `action` */
export function requestConfirm(options: PendingConfirm): void {
  pending = options;
  useAppStore.getState().setConfirmDialog(true);
}

/**
 * 提示一条信息 (如"打开项目失败")。
 *
 * 与 `requestConfirm` 共用同一个对话框与开关: 一次只可能有一个待处理请求, 分成两套
 * 反而要维护"谁该盖在谁上面"。
 */
export function requestAlert(title: string, description: string): void {
  requestConfirm({ title, description, confirmLabel: '知道了', info: true, action: () => {} });
}

/** 当前待确认的内容 (供对话框渲染) */
export function pendingConfirm(): PendingConfirm | null {
  return pending;
}

/** 用户的选择; `accepted` 为真时执行待确认的动作 */
export function resolveConfirm(accepted: boolean): void {
  const current = pending;
  pending = null;
  useAppStore.getState().setConfirmDialog(false);
  if (accepted && current) current.action();
}
